        vertices[base + 5] = u.normals?.[v * 3 + 2] ?? 1;
        vertices[base + 6] = u.uvs?.[v * 2] ?? 0;
        vertices[base + 7] = u.uvs?.[v * 2 + 1] ?? 0;
